examples.template:
MonarchSessionList(
    sessions,
    footnote: {{footnote}},
    onSignOut: { id in
        // The app ends the session on the server.
        try await Task.sleep(for: .milliseconds(300))
        sessions.removeAll { $0.id == id }
    },
    onSignOutOthers: { ids in
        try await Task.sleep(for: .milliseconds(300))
        sessions.removeAll { ids.contains($0.id) }
    }
)

